// "Forgot password" by mobile number. Called by the app as
// supabase.functions.invoke("request-password-reset-by-mobile", { body: { mobileNumber } })
// with no session, so verify_jwt = false (config.toml).
//
// There is no SMS: the number is only used to find the account, and the normal
// Supabase reset email is sent to the address already on that account. The
// caller always gets the same { ok: true } whether or not a number matched, so
// it cannot be used to discover registered numbers, and the email address is
// never returned.
//
// Abuse / enumeration controls: rate limited per IP (10/hour) and per number
// (3/hour), counted before any lookup; over-limit calls get the SAME generic
// { ok: true } (a distinct 429 would let an attacker tell "known" from "unknown"
// once the per-number budget runs out). The email is sent in the background so
// response time does not differ between a known and an unknown number.
import { createClient } from "npm:@supabase/supabase-js@2";
import { handleOptions, jsonResponse } from "../_shared/cors.ts";
import { normalizePhoneNumber } from "../_shared/phone.ts";
import { supabaseAdmin } from "../_shared/supabaseAdmin.ts";
import { clientIp, withinLimit } from "../_shared/rateLimit.ts";

// Must also be in Supabase Auth -> URL Configuration -> Redirect URLs.
const PASSWORD_RESET_REDIRECT_URL = "https://medveda.in/reset-password";

const generic = () => jsonResponse({ ok: true });

Deno.serve(async (req: Request): Promise<Response> => {
  const preflight = handleOptions(req);
  if (preflight) return preflight;
  if (req.method !== "POST") return jsonResponse({ error: "Method not allowed" }, 405);

  let phone: string | null = null;
  try {
    phone = normalizePhoneNumber((await req.json()).mobileNumber);
  } catch {
    return generic();
  }
  if (!phone) return generic();

  // Per IP, per IP+number, and a per-number ceiling across IPs (bounds mail-bombing a
  // victim's inbox without letting one client exhaust the number's whole budget).
  const ip = clientIp(req);
  if (!(await withinLimit(`reset-ip:${ip}`, 10, 3600))
      || !(await withinLimit(`reset-ip-phone:${ip}:${phone}`, 3, 3600))
      || !(await withinLimit(`reset-phone:${phone}`, 6, 3600))) {
    return generic();
  }

  const url = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  if (!url || !anonKey) {
    console.error("request-password-reset-by-mobile: missing SUPABASE_URL / SUPABASE_ANON_KEY");
    return generic();
  }

  const { data: profile, error: lookupError } = await supabaseAdmin
    .from("profiles")
    .select("email, blocked")
    .eq("phone_normalized", phone)
    .maybeSingle();
  if (lookupError) {
    console.error("request-password-reset-by-mobile: lookup failed", lookupError.code);
    return generic();
  }
  if (!profile?.email || profile.blocked) return generic();

  const authClient = createClient(url, anonKey, { auth: { persistSession: false, autoRefreshToken: false } });
  const send = authClient.auth
    .resetPasswordForEmail(profile.email, { redirectTo: PASSWORD_RESET_REDIRECT_URL })
    .then(({ error }) => {
      if (error) console.error("request-password-reset-by-mobile: send failed", error.status);
    })
    .catch(() => {});
  // deno-lint-ignore no-explicit-any
  const runtime = (globalThis as any).EdgeRuntime;
  if (runtime?.waitUntil) runtime.waitUntil(send);
  else await send;

  return generic();
});

// supabase/functions/_shared/cors.ts

export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

export function handleOptions(req: Request): Response | null {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  return null;
}

// JSON response helper. "pay" and "verify-payment" used to return HTML
// pages meant for an external browser - Supabase doesn't serve real
// text/html on the default *.supabase.co domain (scripts get sandboxed
// and blocked), which is why the checkout button did nothing. They now
// return JSON, and the checkout UI runs inside the app's own WebView.
export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// Same rule as mobile-app/src/utils/phone.ts (kept in step with it) and the
// database's public.normalize_phone(): E.164 only. Indian 10-digit numbers
// starting 6-9 (and 91XXXXXXXXXX) become +91XXXXXXXXXX.
export function normalizePhoneNumber(value: unknown): string | null {
  if (typeof value !== "string" || value.length > 32) return null;
  const compact = value.trim().replace(/[\s().-]/g, "");
  const withPrefix = compact.startsWith("00") ? `+${compact.slice(2)}` : compact;
  const international = /^[6-9]\d{9}$/.test(withPrefix)
    ? `+91${withPrefix}`
    : /^91[6-9]\d{9}$/.test(withPrefix)
      ? `+${withPrefix}`
      : withPrefix;
  return /^\+[1-9]\d{7,14}$/.test(international) ? international : null;
}

import { createClient } from "npm:@supabase/supabase-js@2";

// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are injected automatically
// into every Edge Function's environment - no need to set them manually
// via `supabase secrets set`. The service role key bypasses RLS, which
// this backend needs: it has to read/write orders, purchases, and
// payment_sessions across users, not just the calling user's own rows.
const supabaseUrl = Deno.env.get("SUPABASE_URL");
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!supabaseUrl || !serviceRoleKey) {
  throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY Edge Function environment variable.");
}

export const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey, {
  auth: { persistSession: false, autoRefreshToken: false },
});

// Verifies the bearer token from an incoming request's Authorization
// header and returns the authenticated user - the only thing that should
// ever identify who's paying. Never trust a uid passed as a plain body/
// query param, since that would let anyone buy a product "as" someone
// else.
export async function getUserFromAuthHeader(
  req: Request
): Promise<{ id: string; email?: string } | null> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "");
  if (!token) return null;

  const { data, error } = await supabaseAdmin.auth.getUser(token);
  if (error || !data.user) return null;

  return { id: data.user.id, email: data.user.email ?? undefined };
}

import { supabaseAdmin } from "./supabaseAdmin.ts";

export async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

export function clientIp(req: Request): string {
  const forwarded = req.headers.get("cf-connecting-ip")
    ?? req.headers.get("x-real-ip")
    ?? req.headers.get("x-forwarded-for")?.split(",")[0]
    ?? "unknown";
  return forwarded.trim() || "unknown";
}

// true = within limit. By default fails OPEN on a database error (availability of the
// endpoint; the auth provider's own limits still apply behind it). Pass failClosed for
// brute-force-sensitive endpoints (password login) where "limiter down" must not mean
// "no limit".
export async function withinLimit(
  key: string,
  limit: number,
  windowSeconds: number,
  failClosed = false,
): Promise<boolean> {
  const { data, error } = await supabaseAdmin.rpc("rate_limit_hit", {
    p_key: await sha256Hex(key),
    p_limit: limit,
    p_window_seconds: windowSeconds,
  });
  if (error) {
    console.error("rateLimit: rpc failed", error.code);
    return !failClosed;
  }
  return data === true;
}
